{"implementation":"def solve(case):
    if not isinstance(case, dict) or 'payload' not in case:
        raise ValueError("case must have 'payload'")
    payload = case['payload']
    if not isinstance(payload, dict):
        raise ValueError("payload must be dict")
    if 'threshold' not in payload:
        raise ValueError("missing threshold")
    if 'calls' not in payload:
        raise ValueError("missing calls")
    threshold = payload['threshold']
    calls = payload['calls']
    if not isinstance(calls, list):
        raise ValueError("calls must be list")
    accepted_ids = []
    diagnostics = []
    for call in calls:
        if not isinstance(call, dict):
            raise ValueError("each call must be dict")
        call_id = call.get('call_id')
        if call_id is None:
            raise ValueError("missing call_id")
        loss_without = call.get('loss_without_call')
        loss_with = call.get('loss_with_call')
        pred_tokens = call.get('prediction_tokens')
        parseable = call.get('parseable')
        if None in (loss_without, loss_with, pred_tokens, parseable):
            raise ValueError("missing required fields in call")
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be bool")
        gain = loss_without - loss_with
        norm_gain = gain / max(pred_tokens, 1)
        accepted = parseable and norm_gain >= threshold
        if accepted:
            accepted_ids.append(call_id)
        diagnostics.append({
            "call_id": call_id,
            "gain": round(gain, 6),
            "normalized_gain": round(norm_gain, 6),
            "accepted": accepted
        })
    return {
        "accepted_call_ids": accepted_ids,
        "diagnostics": diagnostics
    }"}
